(function(G){
'use strict';
const VERSION='0.5.3';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function chrome(){return `<div class="mobile-topbar"><div class="mobile-wordmark"><span>D</span><div><strong>DRAFT LAB</strong><small>王者 · 全局BP实验室</small></div></div><button data-action="mobile-tools" aria-label="打开更多工具">更多 <span aria-hidden="true">⋯</span></button></div>`;}
function nav(page,icon){return `<nav class="mobile-bottom-nav" aria-label="手机主导航">${[['draft','draft','BP工作台'],['research','chart','体系研究'],['stats','chart','职业数据'],['more','layers','更多']].map(([id,glyph,name])=>`<button ${id==='more'?'data-action="mobile-tools"':`data-nav="${id}"`} ${page===id||(id==='more'&&!['draft','research','stats'].includes(page))?'aria-current="page"':''}><span aria-hidden="true">${icon(glyph)}</span><span>${name}</span></button>`).join('')}</nav>`;}
function tabs(active,turn,label){return `<div class="mobile-draft-switch"><div class="mobile-turn"><span class="live-dot"></span><strong>${esc(label)}</strong><span>${turn?turn.type==='ban'?'BAN':'PICK':'完成'}</span></div><div role="tablist" aria-label="BP操作区域">${[['heroes','选英雄'],['recommend','看推荐'],['analysis','胜率与阵容']].map(([id,name])=>`<button role="tab" id="tab-${id}" aria-selected="${active===id}" aria-controls="mobile-${id}" data-mobile-panel="${id}">${name}</button>`).join('')}</div></div>`;}
function dock(h,error,turn,disabled){if(!h)return '';return `<section class="mobile-lock-dock" aria-label="确认当前英雄"><div><strong>${esc(h.name)}</strong><small>${esc(error||h.roles.join(' / '))}</small></div><button data-detail="${h.id}" aria-label="查看${esc(h.name)}档案">档案</button><button class="primary" data-lock="${h.id}" ${error||disabled?'disabled':''}>锁定${turn?.type==='ban'?'禁用':'选择'}</button><button class="ghost" data-action="clear-selection" aria-label="取消选中">×</button></section>`;}
function tools(s){return `<div class="mobile-tools-grid">${[['games','真实比赛 / BP回放'],['series','系列赛资源'],['library','英雄档案'],['sources','版本与数据来源']].map(([id,name])=>`<button data-nav="${id}">${name} →</button>`).join('')}</div><div class="sep"></div><label class="form-field">比赛规则<select id="mobile-bo" ${s.actions.length||s.games.length?'disabled':''}><option value="7" ${s.bo===7?'selected':''}>BO7 · 全局BP + 巅峰</option><option value="5" ${s.bo===5?'selected':''}>BO5 · 全局BP</option>${s.bo===1?'<option value="1" selected>BO1 · 附加赛</option>':''}</select></label><label class="form-field section-gap">职业数据时间窗口<select id="mobile-window"><option value="all" ${s.window==='all'?'selected':''}>年总全部 · 144局</option><option value="recent" ${s.window==='recent'?'selected':''}>10月15日起 · 32局</option></select></label><p class="legal-note">时间窗口不证明比赛补丁一致。</p><div class="mobile-tools-grid"><button data-action="new">新建系列赛</button><button data-action="import">导入个人存档</button><button data-action="export">导出个人存档</button><button data-action="help">使用说明</button></div>`;}
G.BPMobile={VERSION,chrome,nav,tabs,dock,tools};
})(globalThis);
